/// `punct`'s last byte from its first, `s`: its next where the two are a pair, and the one after where the three are a triple, as the lean lexer reads an operator.
fn pair_2(src: &[u8], s: usize) -> usize {
    let at = |i: usize| src.get(i).copied().unwrap_or(0);
    let (a, b, c) = (at(s), at(s + 1), at(s + 2));
    match [a, b] {
        [0x2a, 0x2a] | [0x2f, 0x2f] | [0x3d, 0x3d] | [0x21, 0x3d] | [0x3c, 0x3d] | [0x3e, 0x3d] | [0x3c, 0x3c] | [0x3e, 0x3e] | [0x2d, 0x3e] | [0x2b, 0x3d] | [0x2d, 0x3d] | [0x2a, 0x3d] | [0x2f, 0x3d] | [0x25, 0x3d] | [0x26, 0x3d] | [0x7c, 0x3d] | [0x5e, 0x3d] | [0x40, 0x3d] | [0x3a, 0x3d] | [0x3c, 0x3e] => s + 1 + usize::from(matches!([a, b, c], [0x2a, 0x2a, 0x3d] | [0x2f, 0x2f, 0x3d] | [0x3c, 0x3c, 0x3d] | [0x3e, 0x3e, 0x3d])),
        _ => s,
    }
}

